/bin/bash -lc "python3 -m py_compile /workspace/openai_client.py && python3 - <<'PY'
import json
import openai_client

class FakeResponse:
    status = 200
    def read(self):
        return json.dumps({\"output\": [{\"content\": [{\"type\": \"output_text\", \"text\": \"ok\"}]}]}).encode()
    def getheader(self, name):
        return \"req_test\"

class FakeConnection:
    def __init__(self, *args, **kwargs): pass
    def request(self, method, path, body, headers):
        payload = json.loads(body)
        assert method == \"POST\" and path == \"/v1/responses\"
        assert payload == {\"model\": \"gpt-5-mini\", \"input\": \"private test\"}
        assert headers[\"Authorization\"] == \"Bearer test-key\"
    def getresponse(self): return FakeResponse()
    def close(self): pass

original = openai_client.http.client.HTTPSConnection
openai_client.http.client.HTTPSConnection = FakeConnection
try:
    assert openai_client.send_prompt(\"private test\", api_key=\"test-key\") == \"ok\"
finally:
    openai_client.http.client.HTTPSConnection = original
print(\"syntax and mocked transport test passed\")
PY"

